#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/mgmt/mcumgr/smp_client.h>
#include <mcumgr/mcumgr_util.h>

static struct smp_client_transport sct;
static int testing_user_data;
static void *response_ptr;
static int response_status;
static K_SEM_DEFINE(response_sem, 0, 1);
static struct net_buf *response_nb;

/* A transport that does nothing, to test timeouts */
static int smp_client_test_timeout_tx(struct smp_client_transport *sct, struct net_buf *nb)
{
	net_buf_unref(nb);
	return 0;
}

/* A transport that immediately provides a response */
static int smp_client_test_response_tx(struct smp_client_transport *sct, struct net_buf *nb)
{
	/* Free request and call the response function */
	net_buf_unref(nb);
	smp_client_transport_recv_cb(sct, response_nb);
	response_nb = NULL;

	return 0;
}

static void smp_client_test_response_cb(struct smp_client_transport *sct, int status,
					void *user_data)
{
	response_ptr = user_data;
	response_status = status;
	k_sem_give(&response_sem);
}

static void *smp_client_test_setup(void)
{
	smp_client_transport_init(&sct, NULL, NULL, NULL);
	return NULL;
}

static void smp_client_test_before(void *fixture)
{
	response_ptr = NULL;
	response_status = 99;
	k_sem_reset(&response_sem);
}

ZTEST(smp_client, test_buf_alloc)
{
	struct net_buf *nb;

	nb = smp_client_buf_alloc();
	zassert_not_null(nb, "Failed to alloc buf");
	net_buf_unref(nb);
}

ZTEST(smp_client, test_msg_response_handler)
{
	struct net_buf *nb;
	int rc;

	sct.functions.tx = smp_client_test_response_tx;
	response_nb = smp_client_buf_alloc();
	zassert_not_null(response_nb, "Failed to alloc response buf");

	nb = smp_client_buf_alloc();
	zassert_not_null(nb, "Failed to alloc request buf");

	rc = smp_client_send_cmd(&sct, nb, smp_client_test_response_cb,
				 K_NO_WAIT, &testing_user_data);
	zassert_ok(rc, "Failed to send");

	/* Wait for response */
	rc = k_sem_take(&response_sem, K_MSEC(100));
	zassert_ok(rc, "Response failed to trigger callback");

	/* Check callback parameters */
	zassert_equal(response_status, 0, "Incorrect status on response");
	zassert_equal(response_ptr, &testing_user_data, "Incorrect user_data on response");
}

ZTEST(smp_client, test_msg_send_timeout)
{
	struct net_buf *nb;
	int rc;

	sct.functions.tx = smp_client_test_timeout_tx;

	nb = smp_client_buf_alloc();
	zassert_not_null(nb, "Failed to alloc buf");

	/* Use a longer timeout to avoid potential races with the system timer tick */
	rc = smp_client_send_cmd(&sct, nb, smp_client_test_response_cb,
				 K_MSEC(50), &testing_user_data);
	zassert_ok(rc, "Failed to send");

	/* Wait for timeout */
	rc = k_sem_take(&response_sem, K_MSEC(100));
	zassert_ok(rc, "Timeout failed to trigger callback");

	/* Check callback parameters */
	zassert_equal(response_status, -ETIMEDOUT, "Incorrect status on timeout");
	zassert_equal(response_ptr, &testing_user_data, "Incorrect user_data on timeout");
}

ZTEST_SUITE(smp_client, NULL, smp_client_test_setup, smp_client_test_before, NULL, NULL);
